CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, auto_advance INTEGER NOT NULL DEFAULT 1, warning_seconds INTEGER NOT NULL DEFAULT 120, critical_seconds INTEGER NOT NULL DEFAULT 30, overtime_behavior TEXT NOT NULL DEFAULT 'negative', timezone TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS timers (id TEXT PRIMARY KEY, room_id TEXT NOT NULL, title TEXT NOT NULL, speaker TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', duration_ms INTEGER NOT NULL DEFAULT 300000, type TEXT NOT NULL DEFAULT 'countdown', trigger_type TEXT NOT NULL DEFAULT 'manual', scheduled_at TEXT, warning_seconds INTEGER NOT NULL DEFAULT 120, critical_seconds INTEGER NOT NULL DEFAULT 30, overtime_behavior TEXT NOT NULL DEFAULT 'negative', color TEXT NOT NULL DEFAULT '#3b82f6', order_index INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'idle', start_timestamp INTEGER, paused_at INTEGER, remaining_ms INTEGER NOT NULL DEFAULT 300000, flash INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, room_id TEXT NOT NULL, text TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, flash INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS outputs (id TEXT PRIMARY KEY, room_id TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, settings_json TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_logs (id TEXT PRIMARY KEY, room_id TEXT, event TEXT NOT NULL, payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connections (id TEXT PRIMARY KEY, room_id TEXT, name TEXT, role TEXT, ip TEXT, connected_at INTEGER, last_seen INTEGER);
